CREATE OR REPLACE FUNCTION public.wound_text(w jsonb)
 RETURNS text
 LANGUAGE sql
 STABLE
AS $function$
  select 'a '
    || case when (w->>'severity')::double precision > 0.16 then 'deep '
            when (w->>'severity')::double precision > 0.07 then '' else 'light ' end
